#!/usr/bin/env node
// SecureEnroll update script.
// Usage:  node apply_update.js "C:\path\to\Secure_Enroll_all"
//         (the folder that contains the "server" and "client" folders)
// It backs up every file it replaces into "_backup_before_update", then writes the new files.
// It never touches .env, node_modules or the database.
const fs = require('fs');
const path = require('path');

const root = path.resolve(process.argv[2] || '.');
if (!fs.existsSync(path.join(root, 'server')) || !fs.existsSync(path.join(root, 'client'))) {
  console.error('This folder does not contain "server" and "client": ' + root);
  console.error('Usage: node apply_update.js "C:\\path\\to\\Secure_Enroll_all"');
  process.exit(1);
}
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backup = path.join(root, '_backup_before_update', stamp);

const FILES = {
 "client/src/components/PasswordInput.jsx": "",
 "client/src/pages/AccountSettings.jsx": "",
 "client/src/pages/Dashboard.jsx": "",
 "client/src/pages/NewApplication.jsx": "",
 "client/src/pages/Register.jsx": "",
 "client/src/pages/admin/WalkInEnrollmentPage.jsx": "",
 "client/src/styles/theme.css": "",
 "client/src/utils/validators.js": "",
 "server/controllers/admin/schedulesController.js": "",
 "server/controllers/admin/schoolSettingsController.js": "",
 "server/controllers/admin/teachersController.js": "",
 "server/controllers/admin/usersController.js": "",
 "server/controllers/admin/walkInEnrollmentController.js": "",
 "server/controllers/applicationController.js": "",
 "server/controllers/authController.js": "",
 "server/controllers/registrarController.js": "",
 "server/controllers/studentController.js": "",
 "server/db/admin/walkInEnrollment.js": "",
 "server/middleware/auth.js": "",
 "server/middleware/params.js": "",
 "server/middleware/upload.js": "",
 "server/routes/admin/schedulesRoutes.js": "",
 "server/routes/admin/schoolSettingsRoutes.js": "",
 "server/routes/admin/teachersRoutes.js": "",
 "server/routes/admin/usersRoutes.js": "",
 "server/routes/applicationRoutes": "",
 "server/routes/registrar.js": "",
 "server/routes/studentRoutes.js": "",
 "server/utils/dbErrors.js": "",
 "server/utils/validators.js": "",
 "server/validators/common.js": "",
 "server/validators/scheduleValidators.js": "",
 "server/validators/settingsValidators.js": "",
 "server/validators/teacherValidators.js": "",
 "server/validators/userValidators.js": "",
 "server/validators/walkInValidators.js": ""
};

let changed = 0, created = 0, same = 0;
for (const [rel, b64] of Object.entries(FILES)) {
  const target = path.join(root, ...rel.split('/'));
  const data = Buffer.from(b64, 'base64');
  const exists = fs.existsSync(target);
  if (exists && fs.readFileSync(target).equals(data)) { same++; console.log('  same     ' + rel); continue; }
  if (exists) {
    const b = path.join(backup, ...rel.split('/'));
    fs.mkdirSync(path.dirname(b), { recursive: true });
    fs.copyFileSync(target, b);
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, data);
  exists ? changed++ : created++;
  console.log((exists ? '  updated  ' : '  created  ') + rel);
}
console.log(`\nDone: ${changed} updated, ${created} created, ${same} already up to date.`);
if (changed) console.log('Your old files are saved in: ' + backup);
console.log('\nNext: restart the API (cd server, npm run dev) and the client (cd client, npm run dev).');
console.log('No database change is needed. Add _backup_before_update to .gitignore if you use git.');
